def clamp(value, lo, hi):
    """Return `value` limited to the closed interval [lo, hi]."""
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

args.new_string:
def clamp(value, lo, hi):
    """Return `value` limited to the closed interval [lo, hi]."""
    if lo > hi:
        raise ValueError("lo must not be greater than hi")
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

